namespace {

// The checker only needs to hook the PreStmt callback for BinaryOperator.
class SAGenTestChecker : public Checker< check::PreStmt<BinaryOperator> > {
  mutable std::unique_ptr<BugType> BT;

public:
  SAGenTestChecker()
      : BT(new BugType(this, "Potential 32-bit left shift without 64-bit upcasting")) {}

  void checkPreStmt(const BinaryOperator *BOp, CheckerContext &C) const;

private:
  // Look for an upcast of the shift operand itself.
  bool isProperlyCastTo64(const Expr *E, CheckerContext &C) const;
  // The target overflow occurs when a narrow final shift is widened only after
  // that shift; a later shift after widening belongs to a different value stage.
  bool isWidenedAfterFinalShift(const BinaryOperator *BOp,
                                ASTContext &Context) const;
};

bool SAGenTestChecker::isProperlyCastTo64(const Expr *E, CheckerContext &C) const {
  // Look for any cast expression in the subtree of E.
  const CastExpr *CE = findSpecificTypeInChildren<CastExpr>(E);
  if (!CE)
    // Also check if E itself is a CastExpr.
    if (const CastExpr *SelfCE = dyn_cast<CastExpr>(E))
      CE = SelfCE;

  if (CE) {
    QualType DestTy = CE->getType();
    if (DestTy->isIntegerType()) {
      // Get the bit-width of the destination type.
      unsigned width = C.getASTContext().getTypeSize(DestTy);
      if (width >= 64)
        return true;
    }
  }
  return false;
}

bool SAGenTestChecker::isWidenedAfterFinalShift(
    const BinaryOperator *BOp, ASTContext &Context) const {
  const Stmt *Current = BOp;
  bool SawWideConversion = false;

  while (Current) {
    DynTypedNodeList Parents = Context.getParents(*Current);
    if (Parents.size() != 1)
      return false;

    const DynTypedNode &Parent = Parents[0];
    if (const auto *ParentExpr = Parent.get<Expr>()) {
      if (const auto *ParentShift = dyn_cast<BinaryOperator>(ParentExpr)) {
        if (ParentShift != BOp && ParentShift->getOpcode() == BO_Shl)
          return false;
      }

      if (isa<CastExpr>(ParentExpr) && ParentExpr->getType()->isIntegerType() &&
          Context.getTypeSize(ParentExpr->getType()) >= 64)
        SawWideConversion = true;

      Current = ParentExpr;
      continue;
    }

    if (const auto *VD = Parent.get<VarDecl>()) {
      if (VD->getType()->isIntegerType() &&
          Context.getTypeSize(VD->getType()) >= 64)
        SawWideConversion = true;
      return SawWideConversion;
    }

    if (const auto *ParentStmt = Parent.get<Stmt>()) {
      Current = ParentStmt;
      continue;
    }

    return false;
  }

  return false;
}

void SAGenTestChecker::checkPreStmt(const BinaryOperator *BOp, CheckerContext &C) const {
  // We are only interested in left shift operators.
  if (BOp->getOpcode() != BO_Shl)
    return;

  const Expr *LHS = BOp->getLHS();
  if (!LHS)
    return;

  // If the LHS expression is explicitly cast to a 64-bit integer, then no bug.
  if (isProperlyCastTo64(LHS, C))
    return;

  QualType LHSType = LHS->getType();
  // Proceed only if the LHS is an integer type.
  if (!LHSType->isIntegerType())
    return;

  unsigned typeWidth = C.getASTContext().getTypeSize(LHSType);
  // The relevant loss of range is a narrow final shift whose result is only
  // widened when stored in a 64-bit quantity.
  if (typeWidth >= 64 ||
      !isWidenedAfterFinalShift(BOp, C.getASTContext()))
    return;

  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;

  auto report = std::make_unique<PathSensitiveBugReport>(
      *BT, "Potential integer overflow: left shift performed on a 32-bit value without upcasting to 64-bit", N);
  report->addRange(BOp->getSourceRange());
  C.emitReport(std::move(report));
}

} // end anonymous namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker",
      "Detects arithmetic shifts on 32-bit integers without prior upcasting to 64-bit",
      "");
}

